import React, { useEffect, useState } from 'react';
import ForceGraph3D from 'react-force-graph-3d';

function App() {
  const [graphData, setGraphData] = useState({ nodes: [], links: [] });

  // Fetch data from Forge (or API)
  useEffect(() => {
    const fetchData = async () => {
      // Replace with your actual Forge app endpoint
      const response = await fetch('https://mtestwiese.atlassian.net/wiki/rest/forge/1.0/api/content');
    
      if (!response.ok) {
        throw new Error(`HTTP error! Status: ${response.status}`);
      }
  

  
      const data = await response.json();
      console.log('Data from Forge API:', data);
      setGraphData(data);
    };

    fetchData();
  }, []);

  return (
    <div style={{ height: '100vh' }}>
      <ForceGraph3D
        graphData={graphData}
        nodeAutoColorBy="group"
      />
    </div>
  );
}

export default App;
